#include "../renderer.c"
#include <assert.h>
int main(void){char error[512];RenderOptions o;assert(read_scene_settings("example.m3i",&o,error));o.width=o.height=24;char path[]="/private/tmp/stepwidth-import-XXXXXX.m3i";int fd=mkstemps(path,4);assert(fd>=0);close(fd);unlink(path);assert(write_scene_parameters(NULL,o,path,error));float values[]={.00001f,.25f,2.f,NAN};for(int i=0;i<4;i++){unsigned char bytes[4];put32f(bytes,values[i]);fd=open(path,O_RDWR);assert(fd>=0&&pwrite(fd,bytes,4,242)==4);close(fd);assert(read_scene_settings(path,&o,error));assert(scene.raystep_limiter==1&&f32(o.preserved_header+242)==1);char output[]="/private/tmp/stepwidth-saved-XXXXXX.m3i";fd=mkstemps(output,4);assert(fd>=0);close(fd);unlink(output);assert(write_scene_parameters(NULL,o,output,error));fd=open(output,O_RDONLY);assert(fd>=0&&pread(fd,bytes,4,242)==4);close(fd);assert(f32(bytes)==1);unlink(output);}unlink(path);puts("Imported finite and nonfinite Stepwidth limiters normalize to 1.0 in engine state, editable settings, and saved standard headers.");return 0;}
